    98  static inline int pack_string_token(struct flb_pack_state *state,
    99                                      const char *str, int len,
   100                                      msgpack_packer *pck)
   101  {
   102      int s;
   103      int out_len;
   104      char *tmp;
   105      char *out_buf;
   106
   107      if (state->buf_size < len + 1) {
   108          s = len + 1;
   109          tmp = flb_realloc(state->buf_data, s);
   110          if (!tmp) {
   111              flb_errno();
   112              return -1;
   113          }
   114          else {
   115              state->buf_data = tmp;
   116              state->buf_size = s;
   117          }
   118      }
   119      out_buf = state->buf_data;
   120
   121      /* Always decode any UTF-8 or special characters */
   122      out_len = flb_unescape_string_utf8(str, len, out_buf);
   123
   124      /* Pack decoded text */
   125      msgpack_pack_str(pck, out_len);
   126      msgpack_pack_str_body(pck, out_buf, out_len);
   127
   128      return out_len;
