   131  /* Receive a tokenized JSON message and convert it to MsgPack */
   132  static char *tokens_to_msgpack(struct flb_pack_state *state,
   133                                 const char *js,
   134                                 int *out_size, int *last_byte)
   135  {
   136      int i;
   137      int flen;
   138      int arr_size;
   139      const char *p;
   140      char *buf;
   141      const jsmntok_t *t;
   142      msgpack_packer pck;
   143      msgpack_sbuffer sbuf;
   144      jsmntok_t *tokens;
   145
   146      tokens = state->tokens;
   147      arr_size = state->tokens_count;
   148
   149      if (arr_size == 0) {
   150          return NULL;
   151      }
   152
   153      /* initialize buffers */
   154      msgpack_sbuffer_init(&sbuf);
   155      msgpack_packer_init(&pck, &sbuf, msgpack_sbuffer_write);
   156
   157      for (i = 0; i < arr_size ; i++) {
   158          t = &tokens[i];
   159
   160          if (t->start == -1 || t->end == -1 || (t->start == 0 && t->end == 0)) {
   161              break;
   162          }
   163
   164          if (t->parent == -1) {
   165              *last_byte = t->end;
   166          }
   167
   168          flen = (t->end - t->start);
   169          switch (t->type) {
   170          case JSMN_OBJECT:
   171              msgpack_pack_map(&pck, t->size);
   172              break;
   173          case JSMN_ARRAY:
   174              msgpack_pack_array(&pck, t->size);
   175              break;
   176          case JSMN_STRING:
   177              pack_string_token(state, js + t->start, flen, &pck);
   178              break;
   179          case JSMN_PRIMITIVE:
   180              p = js + t->start;
   181              if (*p == 'f') {
   182                  msgpack_pack_false(&pck);
   183              }
   184              else if (*p == 't') {
   185                  msgpack_pack_true(&pck);
   186              }
   187              else if (*p == 'n') {
   188                  msgpack_pack_nil(&pck);
   189              }
   190              else {
   191                  if (is_float(p, flen)) {
   192                      msgpack_pack_double(&pck, atof(p));
   193                  }
   194                  else {
   195                      msgpack_pack_int64(&pck, atol(p));
   196                  }
   197              }
   198              break;
   199          case JSMN_UNDEFINED:
   200              msgpack_sbuffer_destroy(&sbuf);
   201              return NULL;
   202          }
   203      }
   204
   205      *out_size = sbuf.size;
   206      buf = sbuf.data;
   207
   208      return buf;
   209  }
